package cn.zihao.heartbeat;
import android.app.*;import android.os.*;import android.content.*;import android.bluetooth.*;import android.bluetooth.le.*;import android.net.wifi.WifiManager;import org.json.*;import java.util.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;
public class HeartbeatService extends Service {
 interface Listener{void onData(String data);} static volatile Listener listener;static volatile String latest="{\"type\":\"status\",\"status\":\"点击开始连接\",\"devices\":\"等待设备\"}";
 static String snapshot(){return latest;}
 BufferedWriter recording;long recordUntil;
 HandlerThread thread;Handler work;volatile boolean running; BluetoothAdapter adapter;BluetoothGatt gatt;boolean scanning;String status="正在启动",lastLoggedStatus="";
 static final UUID SERVICE=UUID.fromString("5052fff6-4f4e-5f45-4347-5f3030303030"),NOTIFY=UUID.fromString("5052fff7-4f4e-5f45-4347-5f3030303030"),WRITE=UUID.fromString("5052fff8-4f4e-5f45-4347-5f3030303030"),CCC=UUID.fromString("00002902-0000-1000-8000-00805f9b34fb");
 Detector detector=new Detector();byte[] buffer=new byte[0];long packets,beats,lastData,lastSeq=-1,sessionStart,sequence;String token;DatagramSocket udp;Thread receiver;PowerManager.WakeLock wake;WifiManager.MulticastLock multicast;
 static class Peer{InetAddress ip;int port;String stamp;long seen,acks;}
 final Map<String,Peer> peers=new HashMap<>();
 @Override public IBinder onBind(Intent i){return null;}
 @Override public void onCreate(){super.onCreate();thread=new HandlerThread("HeartbeatIO",android.os.Process.THREAD_PRIORITY_DISPLAY);thread.start();work=new Handler(thread.getLooper());}
 @Override public int onStartCommand(Intent i,int f,int id){
  NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("ecg","心电连接",NotificationManager.IMPORTANCE_LOW));
  PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);
  startForeground(1,new Notification.Builder(this,"ecg").setContentTitle("心跳联动运行中").setContentText("手机接收心电并转发至 LED / StickS3").setSmallIcon(android.R.drawable.ic_media_play).setContentIntent(open).setOngoing(true).build());
  if(i!=null&&i.hasExtra("record_seconds")){int seconds=Math.max(10,Math.min(600,i.getIntExtra("record_seconds",180)));work.post(()->beginRecording(seconds));}
  if(!running){running=true;work.post(()->{try{initNetwork();wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"heartbeat:stream");wake.acquire();adapter=getSystemService(BluetoothManager.class).getAdapter();scan();work.postDelayed(watchdog,1000);}catch(Exception e){status="启动失败："+e.getMessage();publish(null);}});}return START_NOT_STICKY;
 }
 void initNetwork()throws Exception{
  token=new String(getAssets().open("token").readAllBytes(),StandardCharsets.UTF_8).trim();long seed=Long.parseLong(new String(getAssets().open("sequence").readAllBytes()).trim());
  sequence=Math.max(seed,getSharedPreferences("wireless",0).getLong("sequence",seed));reserveSequence();
  udp=new DatagramSocket(null);udp.setReuseAddress(true);udp.bind(new InetSocketAddress(8766));udp.setBroadcast(true);udp.setSoTimeout(1000);
  WifiManager wm=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);multicast=wm.createMulticastLock("heartbeat-discovery");multicast.setReferenceCounted(false);multicast.acquire();
  receiver=new Thread(()->{byte[] b=new byte[1500];while(running){try{DatagramPacket packet=new DatagramPacket(b,b.length);udp.receive(packet);String data=new String(packet.getData(),0,packet.getLength(),StandardCharsets.UTF_8);InetAddress ip=packet.getAddress();int port=packet.getPort();work.post(()->hello(data,ip,port));}catch(SocketTimeoutException e){}catch(Exception e){if(running)work.post(()->{status="无线端口异常";publish(null);});break;}}},"HeartbeatUDP");receiver.start();
 }
 long reservedUntil;
 void reserveSequence(){reservedUntil=sequence+1000000;getSharedPreferences("wireless",0).edit().putLong("sequence",reservedUntil).commit();}
 void hello(String data,InetAddress ip,int port){try{String[] p=data.split("\\|");if(p.length<4||!token.equals(p[0])||!(p[2].equals("led")||p[2].equals("stick")))return;
  if(p[1].equals("HELLO")){Long.parseLong(p[3]);Peer peer=peers.get(p[2]);if(peer==null){peer=new Peer();peers.put(p[2],peer);}peer.ip=ip;peer.port=port;peer.stamp=p[3];peer.seen=SystemClock.elapsedRealtime();}
  else if(p[1].equals("ACK")){Peer peer=peers.get(p[2]);if(peer!=null&&peer.ip.equals(ip)&&peer.port==port)peer.acks++;}
 }catch(Exception ignored){}}
 void send(String payload,String only){if(udp==null||udp.isClosed())return;sequence++;if(sequence>=reservedUntil-1)reserveSequence();for(Map.Entry<String,Peer> entry:peers.entrySet()){Peer p=entry.getValue();if(SystemClock.elapsedRealtime()-p.seen>600||(only!=null&&!only.equals(entry.getKey())))continue;try{byte[] b=(token+"|"+p.stamp+"|"+(sequence&0xffffffffL)+"|"+payload).getBytes(StandardCharsets.UTF_8);udp.send(new DatagramPacket(b,b.length,p.ip,p.port));}catch(Exception ignored){}}}
 void scan(){if(!running)return;disconnect();detector=new Detector();buffer=new byte[0];lastSeq=-1;sessionStart=SystemClock.elapsedRealtime();lastData=0;
  if(adapter==null||!adapter.isEnabled()){status="请打开手机蓝牙";publish(null);work.postDelayed(retry,3000);return;}
  try{status="扫描 ECG-D01M01（请退出 OMRON Plus 实时页面）";publish(null);scanning=true;adapter.getBluetoothLeScanner().startScan(Collections.singletonList(new ScanFilter.Builder().setDeviceName("ECG-D01M01").build()),new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).build(),scanCallback);work.postDelayed(scanTimeout,20000);}catch(Exception e){status="蓝牙扫描失败："+e.getMessage();publish(null);work.postDelayed(retry,3000);}
 }
 final Runnable retry=()->scan();final Runnable scanTimeout=()->{if(scanning){stopScan();status="未找到心电贴，正在重试";publish(null);work.postDelayed(retry,2000);}};
 void stopScan(){work.removeCallbacks(scanTimeout);if(scanning){scanning=false;try{adapter.getBluetoothLeScanner().stopScan(scanCallback);}catch(Exception ignored){}}}
 final ScanCallback scanCallback=new ScanCallback(){@Override public void onScanResult(int type,ScanResult result){work.post(()->{if(!running||!scanning)return;stopScan();status="正在连接心电贴";publish(null);gatt=result.getDevice().connectGatt(HeartbeatService.this,false,callback,BluetoothDevice.TRANSPORT_LE);sessionStart=SystemClock.elapsedRealtime();});}@Override public void onScanFailed(int code){work.post(()->{stopScan();status="扫描错误 "+code;publish(null);work.postDelayed(retry,3000);});}};
 final BluetoothGattCallback callback=new BluetoothGattCallback(){
  @Override public void onConnectionStateChange(BluetoothGatt g,int s,int state){work.post(()->{if(g!=gatt||!running)return;if(s==0&&state==BluetoothProfile.STATE_CONNECTED){status="读取心电服务";publish(null);g.requestConnectionPriority(BluetoothGatt.CONNECTION_PRIORITY_HIGH);if(!g.requestMtu(247))g.discoverServices();}else if(state==BluetoothProfile.STATE_DISCONNECTED||s!=0)fail("心电连接断开，重试中（"+s+"）");});}
  @Override public void onMtuChanged(BluetoothGatt g,int mtu,int s){work.post(()->{if(g==gatt&&running){android.util.Log.i("Heartbeat","BLE MTU="+mtu+" status="+s);g.discoverServices();}});}
  @Override public void onServicesDiscovered(BluetoothGatt g,int s){work.post(()->{if(g!=gatt||!running)return;BluetoothGattService service=g.getService(SERVICE);if(s!=0||service==null){fail("未找到心电服务");return;}BluetoothGattCharacteristic ch=service.getCharacteristic(NOTIFY);if(ch==null||!g.setCharacteristicNotification(ch,true)){fail("无法订阅心电数据");return;}BluetoothGattDescriptor d=ch.getDescriptor(CCC);if(d==null){fail("通知描述符缺失");return;}d.setValue(BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE);if(!g.writeDescriptor(d))fail("订阅请求失败");});}
  @Override public void onDescriptorWrite(BluetoothGatt g,BluetoothGattDescriptor d,int s){work.post(()->{if(g!=gatt||!running)return;if(s!=0){fail("心电订阅失败");return;}BluetoothGattCharacteristic ch=g.getService(SERVICE).getCharacteristic(WRITE);if(ch==null){fail("心电指令特征缺失");return;}ch.setWriteType(BluetoothGattCharacteristic.WRITE_TYPE_NO_RESPONSE);ch.setValue(new byte[]{(byte)0xaa,4,0,7,0,11,13});if(!g.writeCharacteristic(ch)){fail("实时指令发送失败");return;}status="已连接，等待心电数据";publish(null);});}
  @Override public void onCharacteristicChanged(BluetoothGatt g,BluetoothGattCharacteristic c,byte[] v){byte[] copy=v.clone();work.post(()->{if(g==gatt&&running)receive(copy);});}
  @Override public void onCharacteristicChanged(BluetoothGatt g,BluetoothGattCharacteristic c){if(Build.VERSION.SDK_INT<33){byte[] copy=c.getValue().clone();work.post(()->{if(g==gatt&&running)receive(copy);});}}
 };
 void fail(String reason){disconnect();send("0",null);status=reason;publish(null);work.removeCallbacks(retry);if(running)work.postDelayed(retry,3000);}
 void disconnect(){stopScan();if(gatt!=null){BluetoothGatt old=gatt;gatt=null;try{old.disconnect();old.close();}catch(Exception ignored){}}}
 final Runnable watchdog=new Runnable(){public void run(){if(!running)return;long now=SystemClock.elapsedRealtime();if(gatt!=null&&now-(lastData==0?sessionStart:lastData)>(lastData==0?20000:8000))fail("心电数据超时，重连中");publish(null);work.postDelayed(this,1000);}};
 long receivedNotifications;
 void receive(byte[] data){receivedNotifications++;if(receivedNotifications<=6)android.util.Log.i("Heartbeat","Notification bytes="+data.length+" command="+(data.length>1?(data[1]&255):-1));byte[] joined=Arrays.copyOf(buffer,buffer.length+data.length);System.arraycopy(data,0,joined,buffer.length,data.length);buffer=joined;int offset=0;
  while(buffer.length-offset>=6){if((buffer[offset]&255)!=170){offset++;continue;}int len=(buffer[offset+2]&255)*256+(buffer[offset+3]&255);if(len<6||len>4096){offset++;continue;}if(buffer.length-offset<len)break;byte[] frame=Arrays.copyOfRange(buffer,offset,offset+len);offset+=len;int sum=0;for(int j=1;j<len-2;j++)sum+=frame[j]&255;if(frame[len-1]!=13||(sum&255)!=(frame[len-2]&255)||len!=210||frame[1]!=27)continue;
   long seq=0;for(int j=0;j<4;j++)seq|=(long)(frame[4+j]&255)<<(8*j);if(lastSeq!=-1&&seq!=((lastSeq+1)&0xffffffffL)){detector=new Detector();send("0",null);}lastSeq=seq;
   try{JSONArray samples=new JSONArray(),indices=new JSONArray(),times=new JSONArray();StringBuilder wave=new StringBuilder();long now=System.currentTimeMillis();
    for(int j=0;j<100;j++){int x=(short)((frame[8+2*j]&255)|((frame[9+2*j]&255)<<8));samples.put(x);wave.append(',').append(x);if(detector.feed(x)){indices.put(j);times.put(now);beats++;send("B",null);}}
    packets++;lastData=SystemClock.elapsedRealtime();status="实时接收";Integer bpm=detector.bpm();send("E,"+(bpm==null?0:bpm)+wave,"stick");
    JSONObject event=new JSONObject();event.put("type","ecg");event.put("samples",samples);event.put("beat_indices",indices);event.put("beat_times_ms",times);event.put("playback_at_ms",now);event.put("sequence",seq);event.put("bpm",bpm==null?JSONObject.NULL:bpm);publish(event);record(event);
   }catch(Exception e){android.util.Log.e("Heartbeat","Frame processing",e);}
  }buffer=Arrays.copyOfRange(buffer,offset,buffer.length);if(buffer.length>8192)buffer=new byte[0];
 }
 void beginRecording(int seconds){try{closeRecording();File folder=new File(getExternalFilesDir(null),"experiments");folder.mkdirs();File file=new File(folder,"ecg-"+System.currentTimeMillis()+".jsonl");recording=new BufferedWriter(new FileWriter(file));recordUntil=SystemClock.elapsedRealtime()+seconds*1000L;android.util.Log.i("HeartbeatExperiment","RECORD_START "+file.getAbsolutePath()+" seconds="+seconds);}catch(Exception e){android.util.Log.e("HeartbeatExperiment","Recording failed",e);}}
 void record(JSONObject event){if(recording==null)return;if(SystemClock.elapsedRealtime()>recordUntil){closeRecording();return;}try{JSONObject copy=new JSONObject(event.toString());copy.put("received_elapsed_ms",SystemClock.elapsedRealtime());copy.put("received_wall_ms",System.currentTimeMillis());recording.write(copy.toString());recording.newLine();recording.flush();}catch(Exception e){android.util.Log.e("HeartbeatExperiment","Recording write failed",e);closeRecording();}}
 void closeRecording(){if(recording!=null){try{recording.close();}catch(Exception ignored){}recording=null;android.util.Log.i("HeartbeatExperiment","RECORD_END");}}
 void publish(JSONObject event){try{if(event==null){event=new JSONObject();event.put("type","status");}event.put("status",status);event.put("mode","low_latency");event.put("packets",packets);event.put("beats",beats);event.put("source","live");event.put("sample_rate",250);event.put("last_data",System.currentTimeMillis()/1000.);StringBuilder d=new StringBuilder();for(String name:new String[]{"led","stick"}){Peer p=peers.get(name);d.append(name.equals("led")?"ESP32 ":"StickS3 ");d.append(p!=null&&SystemClock.elapsedRealtime()-p.seen<1000?"在线 · 回执 "+p.acks:"未发现");d.append("  ");}event.put("devices",d.toString());JSONObject deviceStates=new JSONObject();for(String name:new String[]{"led","stick"}){Peer peer=peers.get(name);JSONObject ds=new JSONObject();ds.put("online",peer!=null&&SystemClock.elapsedRealtime()-peer.seen<1000);ds.put("acks",peer==null?0:peer.acks);deviceStates.put(name,ds);}event.put("device_states",deviceStates);latest=event.toString();if(!status.equals(lastLoggedStatus)||("ecg".equals(event.optString("type"))&&packets%25==0)){android.util.Log.i("Heartbeat",status+" packets="+packets+" beats="+beats+" "+d);lastLoggedStatus=status;}Listener l=listener;if(l!=null)l.onData(latest);}catch(Exception ignored){}}
 @Override public void onDestroy(){running=false;work.post(()->{work.removeCallbacksAndMessages(null);closeRecording();send("0",null);disconnect();if(udp!=null)udp.close();if(wake!=null&&wake.isHeld())wake.release();if(multicast!=null&&multicast.isHeld())multicast.release();status="已停止连接";publish(null);thread.quitSafely();});super.onDestroy();}
}
